// Finite boundary vocabulary for strategic-plan-10. Coordinates refer to tile edges.
export const SIZE=240, SIDES=['north','east','south','west'];
export const TRANSFORMS=Array.from({length:8},(_,i)=>({turns:i%4,mirror:i>=4}));
export function transformPoint([x,y],{turns=0,mirror=false},size=SIZE){if(mirror)x=size-x;for(let i=0;i<turns;i++)[x,y]=[size-y,x];return [x,y];}
export function portPoint(p){const n=p.slot*80;return p.side==='north'?[n,0]:p.side==='east'?[SIZE,n]:p.side==='south'?[n,SIZE]:[0,n];}
export function transformPort(p,t){const [x,y]=transformPoint(portPoint(p),t);return {side:y===0?'north':x===SIZE?'east':y===SIZE?'south':'west',slot:(y===0||y===SIZE?x:y)/80};}
export function transformConfig(c,t){return {...c,roads:c.roads.map(side=>transformPort({side,slot:1.5},t).side).sort(),feature:c.feature?{kind:c.feature.kind,ports:c.feature.ports.map(p=>transformPort(p,t)).sort((a,b)=>JSON.stringify(a).localeCompare(JSON.stringify(b)))}:null};}
export function configKey(c){const f=c.feature;return (f?f.kind+'-'+f.ports.map(p=>p.side[0]+p.slot).sort().join('-'):'land')+'-road-'+(c.roads.map(s=>s[0]).sort().join('')||'none');}
export function canonical(c){return TRANSFORMS.map(t=>({config:transformConfig(c,t),transform:t})).sort((a,b)=>configKey(a.config).localeCompare(configKey(b.config)))[0];}
export function configurations(){const all=[];for(let mask=0;mask<16;mask++)all.push({feature:null,roads:SIDES.filter((_,i)=>mask&(1<<i))});for(const kind of ['river','cliff'])for(let a=0;a<4;a++)for(let b=a+1;b<4;b++)for(const x of [1,2])for(const y of [1,2]){const feature={kind,ports:[{side:SIDES[a],slot:x},{side:SIDES[b],slot:y}]};all.push({feature,roads:[]});if(b-a===2)all.push({feature,roads:SIDES.filter((_,i)=>i!==a&&i!==b)});}return all;}
export function catalog(){const groups=new Map();for(const raw of configurations()){const {config}=canonical(raw),key=configKey(config);if(!groups.has(key))groups.set(key,{config,equivalents:[]});groups.get(key).equivalents.push(raw);}const entries=[];for(const [key,g]of groups){const f=g.config.feature,roads=g.config.roads.length;let roles=f?['countryside']:['countryside','village','town','city','fortress'];if(f?.kind==='river'&&roads)roles.push('village','town','city');for(const role of roles){if(!f&&((role==='countryside'&&roads===1)||(role!=='countryside'&&roads===0)))continue;const facilities=role==='town'?[[],['workshop']]:role==='city'?[[],['factory'],['workshop'],['factory','workshop']]:[[]];for(const fs of facilities){const id=role+(fs.length?'-'+fs.join('-'):'')+'--'+key;entries.push({id,kind:'sector-placeholder',version:1,status:'placeholder',role,facilities:fs,difficulties:role==='village'?['easy','medium']:['easy','medium','hard'],config:g.config,equivalents:g.equivalents,allowedTransforms:TRANSFORMS,variants:['placeholder.json'],notes:f?.kind==='cliff'?['Cliff wall and passage footprint only; high bank and elevation contracts await authoring.']:[]});}}}
// Tutorial orientation belongs to the whole six-sector group, never independent mirroring.
for(const [step,travel]of [[1,['north','west']],[2,['north','east']],[3,['west','south']],[4,['north','east','south']],[5,['south','east']],[6,['west']]])entries.push({id:'tutorial-step-'+step,kind:'sector-placeholder',version:1,status:'placeholder',role:step>=5?'town':'tutorial',facilities:[],difficulties:['easy'],config:{feature:null,roads:[]},tutorialStep:step,travel,allowedTransforms:TRANSFORMS.slice(0,4),variants:['placeholder.json'],notes:['Layout reservation only. Author plateau perimeter, elevations and the town connection as one six-sector group (town 5/6, plateau 4/3, plateau 2/1).']});return entries.sort((a,b)=>a.id.localeCompare(b.id));}
export function featureLine(c){if(!c.feature)return [];const [a,b]=c.feature.ports.map(portPoint);const inset=p=>[p[0]===0?12:p[0]===SIZE?SIZE-12:p[0],p[1]===0?12:p[1]===SIZE?SIZE-12:p[1]];return [a,inset(a),inset(b),b];}
export function previewSVG(entry){const c=entry.config,points=featureLine(c).map(p=>p.map(n=>n/2).join(',')).join(' '),roads=c.roads.map(side=>{const [x,y]=portPoint({side,slot:1.5});return `<path d="M${x/2} ${y/2}L60 60"/>`;}).join('');const ports=[...(c.feature?.ports||[]),...c.roads.map(side=>({side,slot:1.5}))].map(p=>{const [x,y]=portPoint(p);return `<circle cx="${x/2}" cy="${y/2}" r="2" fill="#b2342b"/><text x="${Math.max(7,Math.min(111,x/2))}" y="${Math.max(9,Math.min(115,y/2))}" font-size="6" text-anchor="middle">${p.slot===1.5?'½':p.slot===1?'⅓':'⅔'}</text>`;}).join('');const travel=(entry.travel||[]).map(side=>{const [x,y]=portPoint({side,slot:1.5});return `<path d="M60 60L${x/2} ${y/2}" stroke="#47774c" stroke-dasharray="3 2" fill="none"/><text x="60" y="80" font-size="6" text-anchor="middle">Travel reservation</text>`;}).join('');return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-5 -5 130 130"><rect width="120" height="120" fill="#dad9b5" stroke="#9b9479"/><path d="M40 0V120M80 0V120M0 40H120M0 80H120" stroke="#bebca0" stroke-width=".4"/><polyline points="${points}" fill="none" stroke="${c.feature?.kind==='river'?'#478f9e':'#655549'}" stroke-width="${c.feature?.kind==='river'?3:6}"/><g fill="none" stroke="#e9dfc9" stroke-width="5">${roads}</g><g fill="none" stroke="#676969" stroke-width="3">${roads}</g>${ports}${travel}<text x="60" y="48" text-anchor="middle" font-size="7" fill="#70251e">${entry.tutorialStep?'Tutorial '+entry.tutorialStep:entry.role}</text></svg>`;}
